    @Override
    public ResponseEntity<?> handleDownloadFile(String id) {

        try {
            DocumentDTO document = documentService.findById(id);
            if (document == null) {
                return ResponseEntity.status(HttpStatus.NOT_FOUND).body("Document not found");
            }

            String fileUrl = document.getUrl();
            if (fileUrl == null || fileUrl.isEmpty()) {
                return ResponseEntity.status(HttpStatus.NOT_FOUND).body("File URL not found");
            }

            InputStream fileStream = minioService.downloadFile(fileUrl);
            if (fileStream == null) {
                return ResponseEntity.status(HttpStatus.NOT_FOUND).body("File not found in MinIO");
            }

            HttpHeaders headers = new HttpHeaders();
            headers.setContentType(MediaType.APPLICATION_OCTET_STREAM);
            headers.setContentDispositionFormData("attachment", document.getFilename());

            return ResponseEntity.ok()
                    .headers(headers)
                    .body(new InputStreamResource(fileStream));

        } catch (Exception e) {
            logger.error(e.getMessage());
            e.printStackTrace();
            return ResponseEntity.status(HttpStatus.BAD_REQUEST).body(e.getMessage());
        }

    }

