    private String uploadToMinio(MultipartFile file, String fileName) throws Exception {
        // Upload the file to MinIO
        try (InputStream inputStream = file.getInputStream()) {

            String url = minioService.uploadFile(fileName, inputStream, file.getSize(), file.getContentType());
            System.out.println("File uploaded to MinIO: " + url);
            return url;

        } catch(Exception e) {
            e.printStackTrace();
            throw new DocumentServiceException("Error uploading file: " + file.getOriginalFilename());
        }
    }

    private Map<String, Object> uploadToProcessingService(MultipartFile file) {
        // This method is a placeholder for any additional processing service upload logic
        // You can implement it as needed

        File convFile = null;
        try {
            convFile = File.createTempFile("upload_", "_" + file.getOriginalFilename());
            file.transferTo(convFile);

            HttpHeaders headers = new HttpHeaders();
            headers.setContentType(MediaType.MULTIPART_FORM_DATA);

            MultiValueMap<String, Object> body = new LinkedMultiValueMap<>();
            body.add("file", new FileSystemResource(convFile));

            HttpEntity<MultiValueMap<String, Object>> requestEntity = new HttpEntity<>(body, headers);

            ResponseEntity<HashMap<String, Object>> uploadResponse = restTemplate.exchange(
                    solrProcessorUrl + "/upload-pdf/",
                    org.springframework.http.HttpMethod.POST,
                    requestEntity,
                    new ParameterizedTypeReference<HashMap<String, Object>>() {}
            );

            return uploadResponse.getBody();
        } catch (Exception e) {
            logger.warn("Failed to upload to processing service: " + e.getMessage());
            e.printStackTrace();
            return null;
        } finally {
            if (convFile != null && convFile.exists()) {
                convFile.delete();
            }
        }
    }

